568	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
569	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
570		type pending struct {
571			id  seriesID
572			ref SeriesRef
573			ts  int64
574			val float64
575		}
576	
577		added := 0
578		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
579		seen := make(map[seriesID]map[int64]float64)
580		// 仅记录需要落盘的新增点；校验全部通过后才提交。
581		commits := make([]pending, 0, len(items))
582	
583		failAt := func(index int, msg string) *LineError {
584			return &LineError{Status: "error", Index: index, Error: msg}
585		}
586		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
587			return &LineError{
588				Status: "error",
589				Index:  index,
590				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
591					ref, ts, formatFloat(existing), formatFloat(submitted)),
592				Conflict: &Conflict{
593					// 标签必须复制：冲突结果是本次失败的独立记录，
594					// 调用方修改它不能改动已存序列的身份。
595					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
596					Timestamp: ts,
597					Existing:  existing,
598					Submitted: submitted,
599				},
600			}
601		}
602	
603		for i, item := range items {
604			pos := i + 1
605			p, err := parseSample(item)
606			if err != nil {
607				return nil, failAt(pos, err.Error())
608			}
609	
610			id := makeSeriesID(p.name, p.labels)
611			ref := SeriesRef{Name: p.name, Labels: p.labels}
612	
613			if byTS, ok := seen[id]; ok {
614				if old, ok := byTS[p.ts]; ok {
615					if old != p.value {
616						return nil, conflictAt(pos, ref, p.ts, old, p.value)
617					}
618					// 同批内重复出现且数值相同：重复，成功忽略。
619					continue
620				}
621			}
622			if sr, ok := s.series[id]; ok {
623				if old, ok := sr.points[p.ts]; ok {
624					if old != p.value {
625						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
626					}
627					// 与此前批次已写入的值相同：重复，成功忽略。
628					if seen[id] == nil {
629						seen[id] = map[int64]float64{}
630					}
631					seen[id][p.ts] = p.value
632					continue
633				}
634			}
635	
636			added++
637			if seen[id] == nil {
638				seen[id] = map[int64]float64{}
639			}
640			seen[id][p.ts] = p.value
641			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
642		}
643	
644		// 全部采样点合法且无冲突，原子提交本批新增点。
645		for _, c := range commits {
646			sr := s.series[c.id]
647			if sr == nil {
648				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
649				s.series[c.id] = sr
650			}
651			sr.points[c.ts] = c.val
652		}
653	
654		return s.snapshot(added, len(items)-added), nil
655	}
656	
657	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
658	func formatFloat(v float64) string {
659		return strconv.FormatFloat(v, 'g', -1, 64)
660	}
661	
662	type parsedQuery struct {
663		name   string
664		start  int64
665		end    int64
666		labels map[string]string
667	}
668	
669	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
670	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
671		q, err := parseQuery(raw)
672		if err != nil {
673			return nil, &LineError{Status: "error", Error: err.Error()}
674		}
675		if q.start > q.end {
676			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
677				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
678		}
679		return s.runQuery(q), nil
680	}
681	
682	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
683	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
684	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
685		var q parsedQuery
686		err := parseStrictObject(raw,
687			"each query must be a JSON object",
688			"unexpected content after the query object",
689			[]string{"op", "name", "start", "end"},
690			map[string]fieldReader{
691				"op": func(dec *json.Decoder) error {
692					t, err := dec.Token()
693					if err != nil {
694						return err
695					}
696					op, ok := t.(string)
697					if !ok {
698						return fmt.Errorf(`field "op" must be a string`)
699					}
700					if op != "query" {
701						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
702					}
703					return nil
704				},
705				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
706				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
707				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
708				"labels": func(dec *json.Decoder) error {
709					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
710				},
711			})
712		return q, err
713	}
714	
715	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
716	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
717	func labelsMatch(want, stored map[string]string) bool {
718		for k, v := range want {
719			got, ok := stored[k]
720			if !ok || got != v {
721				return false
722			}
723		}
724		return true
725	}
726	
727	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
728	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
729	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
730	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
731		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
732		out := make([]QuerySeries, 0)
733		for _, os := range s.organizeSeries() {
734			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
735				continue
736			}
737			points := sortedSeriesPoints(os.sr, inRange)
738			if len(points) == 0 {
739				continue
740			}
741			values := make([]float64, len(points))
742			for i, p := range points {
743				values[i] = p.Value
744			}
745			out = append(out, QuerySeries{
746				Name:    os.ref.Name,
747				Labels:  os.ref.Labels,
748				Count:   len(values),
749				Average: finiteMean(values),
750			})
751		}
752		return &QueryResult{Status: "ok", Op: "query", Series: out}
753	}
754	
755	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
756	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
757	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
758	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
759	// 只有一个点时结果就是该点的值。
760	func finiteMean(values []float64) float64 {
761		sum := new(big.Rat)
762		r := new(big.Rat)
763		for _, v := range values {
764			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
765			sum.Add(sum, r.SetFloat64(v))
766		}
767		sum.Quo(sum, r.SetInt64(int64(len(values))))
768		return ratToFloat64NearestEven(sum)
769	}
770	
771	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
772	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
773	func ratToFloat64NearestEven(x *big.Rat) float64 {
774		if x.Sign() == 0 {
775			return 0
776		}
777		num := new(big.Int).Set(x.Num())
778		den := x.Denom()
779		neg := num.Sign() < 0
780		if neg {
781			num.Neg(num)
782		}
783	
784		// e 满足 2^e <= num/den < 2^(e+1)。
785		e := floorLog2Rat(num, den)
786		var m *big.Int
787		scale := 0
788		if e >= -1022 {
789			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
790			scale = e - 52
791			m = roundScaledRatio(num, den, scale)
792			if m.BitLen() == 54 {
793				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
794				m.Rsh(m, 1)
795				scale++
796			}
797		} else {
798			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
799			scale = -1074
800			m = roundScaledRatio(num, den, scale)
801		}
802		// m < 2^53，可以精确放入 int64 与 float64。
803		f := math.Ldexp(float64(m.Int64()), scale)
804		if neg {
805			return -f
806		}
807		return f
808	}
809	
810	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
811	func floorLog2Rat(num, den *big.Int) int {
812		k := num.BitLen() - den.BitLen()
813		var t big.Int
814		if k >= 0 {
815			t.Lsh(den, uint(k))
816			if num.Cmp(&t) >= 0 {
817				return k
818			}
819			return k - 1
820		}
821		t.Lsh(num, uint(-k))
822		if t.Cmp(den) >= 0 {
823			return k
824		}
825		return k - 1
826	}
827	
828	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
829	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
830		n := new(big.Int).Set(num)
831		d := new(big.Int).Set(den)
832		if scale >= 0 {
833			d.Lsh(d, uint(scale))
834		} else {
835			n.Lsh(n, uint(-scale))
836		}
837		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
838		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
839		case 1:
840			q.Add(q, big.NewInt(1))
841		case 0:
842			if q.Bit(0) == 1 {
843				q.Add(q, big.NewInt(1))
844			}
845		}
846		return q
847	}
848	
849	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
850	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
851	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
852	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
853	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
854	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
855	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
856	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
857	func (r SeriesRef) String() string {
858		var b strings.Builder
859		b.WriteString(identityText(r.Name))
860		b.WriteByte('{')
861		for i, p := range sortedPairs(r.Labels) {
862			if i > 0 {
863				b.WriteByte(',')
864			}
865			b.WriteString(identityText(p.Key))
866			b.WriteByte('=')
867			b.WriteString(identityText(p.Value))
868		}
869		b.WriteByte('}')
870		return b.String()
871	}
872	
873	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
874	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
875	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
876	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
877	// 因此渲染结果不会把内容字符误读为标签边界。
878	func identityText(s string) string {
879		if s == "" || s != strings.TrimSpace(s) {
880			return strconv.Quote(s)
881		}
882		for _, r := range s {
883			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
884				return strconv.Quote(s)
885			}
886		}
887		return s
888	}
889	
890	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针、
891	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
892	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
893	// 整理好的键值对，供排序比较直接复用。
894	type organizedSeries struct {
895		sr    *storedSeries
896		ref   SeriesRef
897		pairs []labelPair
898	}
899	
900	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
901	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
902	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
903	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
904	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
905	// 每条序列的标签只在遍历时整理一次：排序后的键值对随条目保留，
906	// sort 的反复比较直接复用同一份结果，不会因一条序列参与多次比较
907	// 而反复整理同一套标签。整理结果不复制采样点；采样点的选取与升序
908	// 排列由 sortedSeriesPoints 完成。
909	func (s *MetricStore) organizeSeries() []organizedSeries {
910		out := make([]organizedSeries, 0, len(s.series))
911		for _, sr := range s.series {
912			// 标签必须复制：成功结果是当次操作的独立记录，
913			// 调用方修改结果标签不能改动已存序列的身份。
914			labels := cloneLabels(sr.ref.Labels)
915			out = append(out, organizedSeries{
916				sr:    sr,
917				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
918				pairs: sortedPairs(labels),
919			})
920		}
921		sort.Slice(out, func(i, j int) bool {
922			if out[i].ref.Name != out[j].ref.Name {
923				return out[i].ref.Name < out[j].ref.Name
924			}
925			return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
926		})
927		return out
928	}
929	
930	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
931	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
932	// 区间查询传入闭区间判定，查询只选取区间内的点。
933	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
934	// 也不影响此前或此后取得的其他成功结果。
935	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
936		tsList := make([]int64, 0, len(sr.points))
937		for ts := range sr.points {
938			if keep == nil || keep(ts) {
939				tsList = append(tsList, ts)
940			}
941		}
942		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
943		points := make([]Point, len(tsList))
944		for i, ts := range tsList {
945			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
946		}
947		return points
948	}
949	
950	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
951	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
952	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
953		organized := s.organizeSeries()
954		views := make([]SeriesView, 0, len(organized))
955		for _, os := range organized {
956			views = append(views, SeriesView{
957				Name:   os.ref.Name,
958				Labels: os.ref.Labels,
959				Points: sortedSeriesPoints(os.sr, nil),
960			})
961		}
962		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
963	}
964

