18	func (r *repeatReader) Read(p []byte) (int, error) {
19		if r.n == 0 {
20			return 0, io.EOF
21		}
22		c := len(p)
23		if c > r.n {
24			c = r.n
25		}
26		for i := range p[:c] {
27			p[i] = r.b
28		}
29		r.n -= c
30		return c, nil
31	}
