185	// TestRunIngestConflictMessageDistinguishesRealSeries 端到端验证：两条朴素渲染会
186	// 撞车的序列分别冲突时，解析输出 JSON 后读到的 error 字符串身份部分不同，
187	// 用户只看错误原因就能分辨冲突属于哪条真实序列；名称或标签中的换行与制表符
188	// 呈现为可辨认的文字标记，一条原因不会被误读成多条记录。
189	func TestRunIngestConflictMessageDistinguishesRealSeries(t *testing.T) {
190		lines := []string{
191			// 行 1：两条序列都在时间戳 1000 写入值 1：
192			//   cpu {"a":"1,b=2"}     一个标签，值文本上像两个标签
193			//   cpu {"a":"1","b":"2"} 真实的两个标签
194			`[{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1,b=2"}},` +
195				`{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1","b":"2"}}]`,
196			// 行 2/3：分别对两条序列提交同时间戳的不同值，各自冲突。
197			`[{"name":"cpu","timestamp":1000,"value":2,"labels":{"a":"1,b=2"}}]`,
198			`[{"name":"cpu","timestamp":1000,"value":2,"labels":{"b":"2","a":"1"}}]`,
199			// 行 4：名称含换行、标签值含制表符的序列写入。
200			`[{"name":"cp\nu","timestamp":1,"value":1,"labels":{"ho\tst":"a"}}]`,
201			// 行 5：同一序列（标签键以 	转义书写）提交不同值，冲突。
